$Politics_12_01 = '12.1 Rapports d’Affaires, Listes et Informations Propriétaires';
$Politics_12_01_text = 'En acceptant l’Accord, les IBOs et les Clients reconnaissent que les rapports d’affaires, l’identité et les informations de contact des Clients, IBOs et Clients ou IBOs potentiels (y compris celles disponibles dans les chats de groupe), les informations sur la généalogie d’EVO Global ou d’un IBO, et toute autre information financière, technique ou autre non publique et/ou sensible et diffusée par EVO Global ou appartenant à l’entreprise EVO Global, qu’elle soit écrite ou sous une autre forme, qu’elle soit reçue directement d’EVO Global ou d’autres IBOs, constituent des informations confidentielles et propriétaires et des secrets commerciaux appartenant à Evo Movement International S.A. de C.V.';

    //-------------------------//

$Politics_12_02 = '12.2 Obligation de Confidentialité';
$Politics_12_02_text = 'Les IBOs ne doivent pas utiliser les Informations Confidentielles et Secrets Commerciaux d’Evo Movement International S.A. de C.V. à d’autres fins que la promotion de l’entreprise EVO Global d’un IBO. Un IBO ne peut jamais divulguer les Informations Confidentielles et Secrets Commerciaux non publiques d’Evo Movement International S.A. de C.V. à quiconque en dehors d’EVO Global sans le consentement écrit de la direction d’EVO Global.';

    //-------------------------//

$Politics_12_03 = '12.3 Manquement et Recours';
$Politics_12_03_text = 'Les IBOs reconnaissent que les Informations Confidentielles et Secrets Commerciaux non publiques d’EVO Global sont de telle nature qu’elles les rendent uniques, et que leur divulgation ou utilisation en violation du §12.1 et suivants entraînera un préjudice immédiat et irréparable à EVO Global et aux affaires des IBOs d’EVO Global. En plus de recouvrer tout dommage, EVO Global et ses IBOs auront droit à un recours injonctif accéléré contre tout IBO violant cette disposition dans toute action pour faire respecter leurs droits en vertu de cette section. EVO Global peut demander ce recours injonctif de manière accélérée conformément aux lois internationales et mexicaines applicables. La partie gagnante aura droit à l’octroi des frais d’avocat, frais judiciaires et dépenses.';

    //-------------------------//

$Politics_12_04 = '12.4 Retour de Matériel';
$Politics_12_04_text = 'Un IBO doit immédiatement retourner à EVO Global l’original et toutes les copies de toutes les Informations Confidentielles et Secrets Commerciaux d’EVO Global en sa possession à (1) la résiliation du présent Accord, ou (2) à la demande d’EVO Global.';

